import { Injectable, computed, signal } from '@angular/core';
import { TmdbMovie } from './movie';

export interface WatchItem extends Pick<TmdbMovie, 'id' | 'title' | 'poster_path'> {
  watched: boolean;
}

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
  private readonly _items = signal<WatchItem[]>(JSON.parse(localStorage.getItem('watchlist') ?? '[]'));
  private readonly _announcement = signal('');

  // Signal of the watchlist, so components can react to changes
  items = computed(() => this._items());
  // Screen reader announcements
  announcement = computed(() => this._announcement());
  // How many movies in the watchlist
  count = computed(() => this._items().length);
  // How many of the movies on the watchlist have been watched
  watchedCount = computed(() => this._items().filter(m => m.watched).length);
  // Percentage of the watchlist that has been watched
  progress = computed(() => this.count() ? (this.watchedCount() / this.count()) * 100 : 0);

  // Add a movie to the watchlist, ignore duplicates
  add(movie: TmdbMovie) {
    this._items.update(items => {
      if (items.some(m => m.id === movie.id)) return items;
      return [...items, { id: movie.id, title: movie.title, poster_path: movie.poster_path, watched: false }];
    });
  }

  // Remove a movie from the watchlist
  remove(id: number) {
    this._items.update(items => items.filter(m => m.id !== id));
    this._announcement.set(`Removed ${this._items()[0]?.title ?? 'the movie'} from your watchlist`);
  }

  // Toggle the watched state of a movie
  toggleWatched(id: number) {
    this._items.update(items => items.map(m => (m.id === id ? { ...m, watched: !m.watched } : m)));
    this._announcement.set(`Watched ${this._items().find(m => m.id === id)?.title ?? 'the movie'}`);
  }
}
```

